const orders = await listOrdersForUser(1);
assert.equal(orders.length, 2);
assert.ok(orders.every((o) => o.user_id === 1));
});

test('totalPaidCents counts only paid orders', async () => {
const total = await totalPaidCents();
assert.equal(total, 4200 + 9900 + 500);
});
