+  { method: 'GET', path: '/users/:id', handler: (req, cb) => findUser(Number(req.params.id)).then((r) => cb(null, r), cb) },
+  { method: 'GET', path: '/users/:id/orders', handler: (req, cb) => listOrdersForUser(Number(req.params.id)).then((r) => cb(null, r), cb) },
+  { method: 'GET', path: '/reports/paid-total', handler: (req, cb) => totalPaidCents().then((r) => cb(null, r), cb) },
+  { method: 'GET', path: '/reports/uncaptured-total', handler: (req, cb) => uncapturedTotalCents().then((r) => cb(null, r), cb) },
 ];

 export function listEndpoints() {
import { query } from '../db.js';

export class OrderRepository {
  findByUser(userId) {
    return new Promise((resolve, reject) => {
      query('orders', (o) => o.user_id === userId && o.deleted_at === null,
        (err, rows) => (err ? reject(err) : resolve(rows)));
    });
  }

  findPaid() {
    return new Promise((resolve, reject) => {
      query('orders', (o) => o.status === 'paid' && o.deleted_at === null,
        (err, rows) => (err ? reject(err) : resolve(rows)));
    });
  }
}
import { query } from '../db.js';

export class PaymentRepository {
  findByOrder(orderId) {
    return new Promise((resolve, reject) => {
      query('payments', (p) => p.order_id === orderId,
        (err, rows) => (err ? reject(err) : resolve(rows)));
    });
  }

  findUncaptured() {
    return new Promise((resolve, reject) => {
      query('payments', (p) => p.captured === false,
        (err, rows) => (err ? reject(err) : resolve(rows)));
    });
  }
}
import { query, update } from '../db.js';

// The repository pattern the project is migrating toward: promise-based,
// one place per table, no query construction anywhere else.
export class UserRepository {
  findActive() {
    return new Promise((resolve, reject) => {
      query('users', (u) => u.deleted_at === null, (err, rows) =>
        err ? reject(err) : resolve(rows));
    });
  }

  findById(id) {
    return new Promise((resolve, reject) => {
      query('users', (u) => u.id === id, (err, rows) =>
        err ? reject(err) : resolve(rows[0] ?? null));
    });
  }

  softDelete(id, when) {
    return new Promise((resolve, reject) => {
      update('users', id, { deleted_at: when }, (err, row) =>
        err ? reject(err) : resolve(row));
    });
  }
}

